<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Conway's Game of Life</title>
  <style>
    * {
      margin: 0;
      padding: 0;
      box-sizing: border-box;
    }

    body {
      background: #0a0e27;
      color: #e0e6ff;
      font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      min-height: 100vh;
      padding: 20px;
    }

    h1 {
      margin-bottom: 20px;
      font-size: 2.5em;
      text-shadow: 0 0 10px rgba(100, 200, 255, 0.5);
      letter-spacing: 2px;
    }

    .container {
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 20px;
    }

    #life {
      border: 3px solid #4a9eff;
      background: #050812;
      cursor: crosshair;
      box-shadow: 0 0 20px rgba(74, 158, 255, 0.3);
      min-width: 400px;
      min-height: 400px;
      image-rendering: pixelated;
      image-rendering: crisp-edges;
    }

    .controls {
      display: flex;
      gap: 15px;
      flex-wrap: wrap;
      justify-content: center;
    }

    button {
      padding: 12px 24px;
      font-size: 1em;
      font-weight: 600;
      border: 2px solid #4a9eff;
      background: linear-gradient(135deg, #1a3a52, #0d1f3c);
      color: #e0e6ff;
      border-radius: 6px;
      cursor: pointer;
      transition: all 0.3s ease;
      text-transform: uppercase;
      letter-spacing: 1px;
      box-shadow: 0 0 10px rgba(74, 158, 255, 0.2);
    }

    button:hover {
      background: linear-gradient(135deg, #2a5a72, #1d3f5c);
      box-shadow: 0 0 20px rgba(74, 158, 255, 0.5);
      transform: translateY(-2px);
    }

    button:active {
      transform: translateY(0);
    }

    button#play.playing {
      background: linear-gradient(135deg, #2a5a2a, #1d3f1d);
      border-color: #4aff4a;
      box-shadow: 0 0 20px rgba(74, 255, 74, 0.3);
    }

    .info {
      color: #888;
      font-size: 0.9em;
      text-align: center;
      margin-top: 10px;
    }

    #generation {
      font-size: 1.2em;
      font-weight: bold;
      color: #4aff4a;
      margin-top: 10px;
    }
  </style>
</head>
<body>
  <h1>🌌 Conway's Game of Life</h1>

  <div class="container">
    <canvas id="life"></canvas>

    <div class="controls">
      <button id="step">⏭️ Step</button>
      <button id="play">▶️ Play</button>
      <button id="random">🎲 Random</button>
      <button id="clear">🗑️ Clear</button>
    </div>

    <div id="generation">Generation: 0</div>
    <div class="info">Click or drag to toggle cells alive/dead</div>
  </div>

  <script>
    const GRID_WIDTH = 64;
    const GRID_HEIGHT = 64;
    const CELL_SIZE = 6.25; // 400/64

    let grid = new Uint8Array(GRID_WIDTH * GRID_HEIGHT);
    let generation = 0;
    let isPlaying = false;
    let animationId = null;

    const canvas = document.getElementById('life');
    const ctx = canvas.getContext('2d');

    // Set canvas size
    canvas.width = 400;
    canvas.height = 400;

    const stepBtn = document.getElementById('step');
    const playBtn = document.getElementById('play');
    const randomBtn = document.getElementById('random');
    const clearBtn = document.getElementById('clear');
    const genDisplay = document.getElementById('generation');

    // === Core API exposed on window.life ===
    window.life = {
      w: GRID_WIDTH,
      h: GRID_HEIGHT,

      get(x, y) {
        if (x < 0 || x >= GRID_WIDTH || y < 0 || y >= GRID_HEIGHT) {
          return 0;
        }
        return grid[y * GRID_WIDTH + x];
      },

      set(x, y, v) {
        if (x >= 0 && x < GRID_WIDTH && y >= 0 && y < GRID_HEIGHT) {
          grid[y * GRID_WIDTH + x] = v ? 1 : 0;
          draw();
        }
      },

      step() {
        const newGrid = new Uint8Array(GRID_WIDTH * GRID_HEIGHT);

        for (let y = 0; y < GRID_HEIGHT; y++) {
          for (let x = 0; x < GRID_WIDTH; x++) {
            const idx = y * GRID_WIDTH + x;
            const current = grid[idx];
            const neighbors = countNeighbors(x, y);

            // B3/S23 rules
            if (current === 1) {
              // Survival: 2 or 3 neighbors
              newGrid[idx] = (neighbors === 2 || neighbors === 3) ? 1 : 0;
            } else {
              // Birth: exactly 3 neighbors
              newGrid[idx] = neighbors === 3 ? 1 : 0;
            }
          }
        }

        grid = newGrid;
        generation++;
        draw();
        genDisplay.textContent = `Generation: ${generation}`;
      },

      clear() {
        grid = new Uint8Array(GRID_WIDTH * GRID_HEIGHT);
        generation = 0;
        draw();
        genDisplay.textContent = `Generation: 0`;
      }
    };

    function countNeighbors(x, y) {
      let count = 0;
      for (let dy = -1; dy <= 1; dy++) {
        for (let dx = -1; dx <= 1; dx++) {
          if (dx === 0 && dy === 0) continue;
          const nx = x + dx;
          const ny = y + dy;
          if (nx >= 0 && nx < GRID_WIDTH && ny >= 0 && ny < GRID_HEIGHT) {
            count += grid[ny * GRID_WIDTH + nx];
          }
        }
      }
      return count;
    }

    function draw() {
      ctx.fillStyle = '#050812';
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      ctx.fillStyle = '#4aff4a';
      for (let y = 0; y < GRID_HEIGHT; y++) {
        for (let x = 0; x < GRID_WIDTH; x++) {
          if (grid[y * GRID_WIDTH + x] === 1) {
            ctx.fillRect(x * CELL_SIZE, y * CELL_SIZE, CELL_SIZE, CELL_SIZE);
          }
        }
      }

      // Draw grid lines (faint)
      ctx.strokeStyle = 'rgba(74, 158, 255, 0.1)';
      ctx.lineWidth = 0.5;
      for (let i = 0; i <= GRID_WIDTH; i++) {
        ctx.beginPath();
        ctx.moveTo(i * CELL_SIZE, 0);
        ctx.lineTo(i * CELL_SIZE, canvas.height);
        ctx.stroke();
      }
      for (let i = 0; i <= GRID_HEIGHT; i++) {
        ctx.beginPath();
        ctx.moveTo(0, i * CELL_SIZE);
        ctx.lineTo(canvas.width, i * CELL_SIZE);
        ctx.stroke();
      }
    }

    function getGridCoords(e) {
      const rect = canvas.getBoundingClientRect();
      const x = Math.floor((e.clientX - rect.left) / CELL_SIZE);
      const y = Math.floor((e.clientY - rect.top) / CELL_SIZE);
      return { x, y };
    }

    let isMouseDown = false;

    canvas.addEventListener('mousedown', (e) => {
      isMouseDown = true;
      const { x, y } = getGridCoords(e);
      if (x >= 0 && x < GRID_WIDTH && y >= 0 && y < GRID_HEIGHT) {
        const idx = y * GRID_WIDTH + x;
        grid[idx] = grid[idx] === 1 ? 0 : 1;
        draw();
      }
    });

    canvas.addEventListener('mousemove', (e) => {
      if (!isMouseDown) return;
      const { x, y } = getGridCoords(e);
      if (x >= 0 && x < GRID_WIDTH && y >= 0 && y < GRID_HEIGHT) {
        const idx = y * GRID_WIDTH + x;
        grid[idx] = grid[idx] === 1 ? 0 : 1;
        draw();
      }
    });

    canvas.addEventListener('mouseup', () => {
      isMouseDown = false;
    });

    canvas.addEventListener('mouseleave', () => {
      isMouseDown = false;
    });

    stepBtn.addEventListener('click', () => {
      window.life.step();
    });

    playBtn.addEventListener('click', () => {
      isPlaying = !isPlaying;
      if (isPlaying) {
        playBtn.textContent = '⏸️ Pause';
        playBtn.classList.add('playing');
        function autoStep() {
          if (isPlaying) {
            window.life.step();
            animationId = setTimeout(autoStep, 100);
          }
        }
        autoStep();
      } else {
        playBtn.textContent = '▶️ Play';
        playBtn.classList.remove('playing');
        if (animationId) clearTimeout(animationId);
      }
    });

    randomBtn.addEventListener('click', () => {
      for (let i = 0; i < grid.length; i++) {
        grid[i] = Math.random() > 0.7 ? 1 : 0;
      }
      draw();
    });

    clearBtn.addEventListener('click', () => {
      if (isPlaying) {
        isPlaying = false;
        playBtn.textContent = '▶️ Play';
        playBtn.classList.remove('playing');
        if (animationId) clearTimeout(animationId);
      }
      window.life.clear();
    });

    // Initial draw
    draw();
  </script>
</body>
</html>
